namespace BetaFit.Desktop.Helpers;
public static class FormHelper { public static void StyleGrid(DataGridView g){g.BackgroundColor=Color.FromArgb(22,27,34);g.BorderStyle=BorderStyle.None;g.EnableHeadersVisualStyles=false;g.ColumnHeadersDefaultCellStyle.BackColor=Color.FromArgb(31,38,48);g.ColumnHeadersDefaultCellStyle.ForeColor=Color.White;g.DefaultCellStyle.BackColor=Color.FromArgb(22,27,34);g.DefaultCellStyle.ForeColor=Color.Gainsboro;g.DefaultCellStyle.SelectionBackColor=Color.FromArgb(55,72,92);g.DefaultCellStyle.SelectionForeColor=Color.White;g.RowTemplate.Height=42;g.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;g.AllowUserToAddRows=false;g.ReadOnly=true;} }